class Solution {
public:
    long long minOperationsToMakeMedianK(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int m = nums.size() / 2;
        long long ans = abs(nums[m] - k);
        for (int i = 0; i < m; ++i) {
            if (nums[i] > k) ans += nums[i] - k;
        }
        for (int i = m + 1; i < nums.size(); ++i) {
            if (nums[i] < k) ans += k - nums[i];
        }
        return ans;
    }
};

class Solution {
    public long minOperationsToMakeMedianK(int[] nums, int k) {
        Arrays.sort(nums);
        int m = nums.length / 2;
        long ans = Math.abs((long) nums[m] - k);
        for (int i = 0; i < m; i++) {
            if (nums[i] > k) ans += nums[i] - k;
        }
        for (int i = m + 1; i < nums.length; i++) {
            if (nums[i] < k) ans += k - nums[i];
        }
        return ans;
    }
}

var minOperationsToMakeMedianK = function(nums, k) {
    nums.sort((a, b) => a - b);
    const m = Math.floor(nums.length / 2);
    let ans = Math.abs(nums[m] - k);
    for (let i = 0; i < m; i++) {
        if (nums[i] > k) ans += nums[i] - k;
    }
    for (let i = m + 1; i < nums.length; i++) {
        if (nums[i] < k) ans += k - nums[i];
    }
    return ans;
};
